const ROWS = { B: [{"name":"Дмитрий Орлов","text":"Дмитрий Орлов +7 916 214-08-35 2 февраля 2024 9 Новый: 1 В работе: 1 +4"},{"name":"Анна Гордеева","text":"Анна Гордеева +7 903 551-27-64 20 октября 2026 4 В работе: 4"},{"name":"Нина Фёдорова","text":"Нина Фёдорова +995 555 14-20-77 9 ноября 2026 1 Новый: 1"},{"name":"Андрей Крылов","text":"Андрей Крылов +7 925 880-31-19 2 сентября 2026 3 Сделка: 3"},{"name":"Ринат Хасанов","text":"Ринат Хасанов +7 987 402-66-30 11 августа 2026 3 Потенциальная сделка: 3"},{"name":"Олег Громов","text":"Олег Громов +7 911 333-48-02 30 октября 2026 1 Отказ: 1"},{"name":"Леонид Маслов","text":"Леонид Маслов +7 905 120-77-45 3 ноября 2026 1 Отказ: 1"},{"name":"Татьяна Эльман","text":"Татьяна Эльман +972 52 744-19-83 12 октября 2026 3 В работе: 2 Отказ: 1"}], A: [{"name":"Дмитрий Орлов","text":"Дмитрий Орлов +7 916 214-08-35 2 февраля 2024 9 Новый: 1 В работе: 1 +4"},{"name":"Анна Гордеева","text":"Анна Гордеева +7 903 551-27-64 20 октября 2026 4 В работе: 4"},{"name":"Нина Фёдорова","text":"Нина Фёдорова +995 555 14-20-77 9 ноября 2026 1 Новый: 1"},{"name":"Андрей Крылов","text":"Андрей Крылов +7 925 880-31-19 2 сентября 2026 3 Сделка: 3"},{"name":"Ринат Хасанов","text":"Ринат Хасанов +7 987 402-66-30 11 августа 2026 3 Потенциальная сделка: 3"},{"name":"Олег Громов","text":"Олег Громов +7 911 333-48-02 30 октября 2026 1 Отказ: 1"},{"name":"Леонид Маслов","text":"Леонид Маслов +7 905 120-77-45 3 ноября 2026 1 Отказ: 1"},{"name":"Татьяна Эльман","text":"Татьяна Эльман +972 52 744-19-83 12 октября 2026 3 В работе: 2 Отказ: 1"},{"name":"Ана Силва","text":"Ана Силва +351 912 004-55-71 2 ноября 2026 2 Новый: 1 В работе: 1"},{"name":"Мустафа Йылдыз","text":"Мустафа Йылдыз +90 532 118-20-67 7 ноября 2026 1 В работе: 1"}] };
const ALL = { st: 'all', co: 'all' };
const plural = (n, a, b, c) => { const m = n % 100, d = n % 10; return n + ' ' + (m > 10 && m < 20 ? c : d === 1 ? a : d > 1 && d < 5 ? b : c); };

class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { q: '', f: Object.assign({}, ALL), open: '', cold: !!ZK.S.get('zk.cold'), open0: true };
    this.__off = [];
  }
  componentDidMount() {
    const onDoc = (e) => { if (this.state.open && !(e.target.closest && e.target.closest('.cs'))) this.setState({ open: '' }); };
    document.addEventListener('click', onDoc);
    this.__off = [() => document.removeEventListener('click', onDoc)];
  }
  componentWillUnmount() { this.__off.forEach((f) => f()); }
  renderVals() {
    const S = this.state, set = (o) => this.setState(o), store = ZK.S, nov = ZK.nov(), F = S.f;
    const rows = ROWS[S.cold ? 'A' : 'B'], nw = ZK.newReqs();
    const known = nov ? [] : ZK.REC.map((x) => x.cl);
    const filtered = F.st !== 'all' || F.co !== 'all';
    const hid = {}; let vis = 0;
    rows.forEach((r, i) => {
      let v = !nov && ZK.qmatch(r.text, S.q);
      if (v && filtered) { const recs = ZK.REC.filter((x) => x.cl === r.name); v = recs.some((x) => (F.st === 'all' || x.st === F.st) && (F.co === 'all' || String(x.co || '').split(', ').includes(F.co))); }
      hid['k' + i] = v ? '' : 'zk-hide';
      if (v) vis++;
    });
    const seen = {};
    const newCl = nw.filter((x) => { if (seen[x.name] || known.includes(x.name)) return false; seen[x.name] = 1; return true; }).map((x) => {
      const mine = nw.filter((y) => y.name === x.name);
      const v = ZK.qmatch(x.name + ' ' + x.phone + ' ' + mine.map((y) => y.no).join(' '), S.q) && mine.some((y) => ZK.match(ZK.recOfNew(y), Object.assign({ ty: 'all', pr: 'all', mg: 'all', dt: 'all', sr: 'all' }, F)));
      if (v) vis++;
      return { hid: v ? '' : 'zk-hide', name: x.name, phone: x.phone, date: x.date, n: mine.length };
    });
    const f = {};
    const sel = (k, all, opts) => {
      f[k + 'Cls'] = S.open === k ? 'is-open' : ''; f[k + 'Open'] = S.open === k; f[k + 'Toggle'] = () => set({ open: S.open === k ? '' : k });
      f[k + 'Label'] = F[k] === 'all' ? all : F[k];
      f[k + 'List'] = ['all'].concat(opts).map((o) => ({ t: o === 'all' ? all : o, cur: F[k] === o ? 'is-cur' : '', sel: F[k] === o, pick: () => set({ f: Object.assign({}, F, { [k]: o }), open: '' }) }));
    };
    sel('co', 'Все страны', ZK.uniq(ZK.REC.map((x) => x.co).concat(nw.map((x) => x.co)).join(', ').split(', ')).sort());
    sel('st', 'Все статусы', ZK.STAT);
    const R = nov ? [] : ZK.REC;
    const hasClients = rows.length * (nov ? 0 : 1) + newCl.length > 0;
    return {
      cold: S.cold, notCold: !S.cold, q: S.q, onQ: (ev) => set({ q: ev.target.value }),
      toggleCold: (ev) => { store.set('zk.cold', !!ev.target.checked); set({ cold: !!ev.target.checked }); },
      cnt: ZK.cnt(), f, hid, newCl, anyVis: vis > 0, noRes: hasClients && vis === 0, hasClients, noClients: !hasClients,
      ss: { c: ZK.cnt().k, a: ZK.cnt().z, w: R.filter((x) => x.st === 'В работе').length, d: R.filter((x) => x.st === 'Сделка').length },
      foot: S.cold ? 'Показано ' + plural(vis, 'клиент', 'клиента', 'клиентов') + ', вместе с холодной базой. Холодные клиенты помечены типом «Тип 4: холодный».' : 'Показано ' + plural(vis, 'клиент', 'клиента', 'клиентов') + '. Холодная база скрыта.',
      open0: S.open0, toggle0: () => set({ open0: !S.open0 })
    };
  }
}
